const fs = require("fs");
const path = require("path");

const CJS_INDEX = path.join("dist", "cjs", "src", "index.js");

// tsc compiles `export * as arch from "./arch"` into an eager
// `exports.arch = tslib_1.__importStar(require("./arch"));`, so requiring the package
// root loads all 17 namespaces and their transitive dependency graphs — ~180MB RSS for
// a consumer that only wanted `constants`. ESM consumers are fine (bundlers tree-shake,
// and the package is marked sideEffects-free) but CJS consumers pay in full at runtime.
//
// ES module bindings are static by spec, so this can't be expressed in src/index.ts
// without breaking the ESM build. Instead we rewrite the emitted CJS barrel in place,
// swapping each eager namespace assignment for a self-replacing lazy getter. Every other
// statement tsc emitted is left untouched, so a non-namespace export added to
// src/index.ts survives the rewrite instead of being dropped. Public API is unchanged:
// same keys, same enumerability, same writability, same values.
const EAGER_NAMESPACE = /^exports\.([A-Za-z0-9_$]+) = tslib_1\.__importStar\(require\("(\.[^"]*)"\)\);$/gm;

// Anything still eagerly star-importing after the rewrite means tsc's emit shape drifted
// for some (but not all) namespaces — a silent perf regression we want to fail the build.
const RESIDUAL_EAGER = /^exports\.[A-Za-z0-9_$]+ = .*__importStar\(/gm;

// The helper needs `tslib_1` in scope, so it is injected directly after tsc's own require.
const TSLIB_REQUIRE = 'const tslib_1 = require("tslib");';

const SOURCE_MAP_COMMENT = /^\/\/# sourceMappingURL=.*$\n?/gm;

const LAZY_HELPER = `
// Attach a namespace as a lazy getter that replaces itself with the resolved namespace on
// first access, so subsequent reads are a plain property lookup. Generated by
// scripts/lazify-cjs-index.cjs — edit that script, not this file.
function lazy(name, load) {
  let namespace;
  let loaded = false;
  // tsc emits a plain writable data property; restoring one keeps \`sdk.constants = mock\`
  // working for consumers that monkey-patch a namespace. A consumer that sealed or froze
  // the root leaves this accessor in place and non-configurable, in which case we serve
  // the closure cache rather than throwing on a redefine that cannot succeed.
  const replaceWith = (value) => {
    const descriptor = Object.getOwnPropertyDescriptor(exports, name);
    if (descriptor && descriptor.configurable) {
      Object.defineProperty(exports, name, { value, writable: true, enumerable: true, configurable: true });
    }
  };
  Object.defineProperty(exports, name, {
    configurable: true,
    enumerable: true,
    get() {
      if (!loaded) {
        namespace = tslib_1.__importStar(load());
        loaded = true;
        replaceWith(namespace);
      }
      return namespace;
    },
    set(value) {
      // Assigning before the first read replaces the namespace without ever loading it.
      // On a sealed or frozen root the assignment is dropped, matching the integrity
      // guarantee the consumer asked for (and what an eager data property would do).
      const descriptor = Object.getOwnPropertyDescriptor(exports, name);
      if (!descriptor || !descriptor.configurable) {
        return;
      }
      namespace = value;
      loaded = true;
      replaceWith(value);
    },
  });
}
`;

function lazifyCjsIndex() {
  if (!fs.existsSync(CJS_INDEX)) {
    console.error(`Error: ${CJS_INDEX} not found. Run the CJS build first.`);
    process.exit(1);
  }

  const source = fs.readFileSync(CJS_INDEX, "utf8");

  if (source.includes("function lazy(name, load)")) {
    console.log("CJS index already lazified, skipping");
    return;
  }

  const namespaces = [...source.matchAll(EAGER_NAMESPACE)];

  // Fail loudly rather than silently shipping the eager barrel: a tsc upgrade that
  // changes the emit shape must not quietly regress package-root memory usage.
  if (namespaces.length === 0) {
    console.error(
      `Error: no eager namespace re-exports found in ${CJS_INDEX}. ` +
        "The tsc emit shape has probably changed — update EAGER_NAMESPACE in this script."
    );
    process.exit(1);
  }

  if (!source.includes(TSLIB_REQUIRE)) {
    console.error(
      `Error: could not find \`${TSLIB_REQUIRE}\` in ${CJS_INDEX} to anchor the lazy helper. ` +
        "The tsc emit shape has probably changed — update TSLIB_REQUIRE in this script."
    );
    process.exit(1);
  }

  const lazified = source
    .replace(EAGER_NAMESPACE, (_match, name, request) => `lazy("${name}", () => require("${request}"));`)
    .replace(TSLIB_REQUIRE, `${TSLIB_REQUIRE}\n${LAZY_HELPER}`)
    // Inserting the helper shifts every line below it, so the emitted source map no
    // longer applies. Drop the reference instead of shipping a map that misattributes.
    .replace(SOURCE_MAP_COMMENT, "");

  const residual = [...lazified.matchAll(RESIDUAL_EAGER)];
  if (residual.length > 0) {
    console.error(
      `Error: ${residual.length} eager namespace export(s) survived the rewrite in ${CJS_INDEX}:\n` +
        residual.map(([line]) => `  ${line}`).join("\n") +
        "\nThe tsc emit shape has probably changed — update EAGER_NAMESPACE in this script."
    );
    process.exit(1);
  }

  fs.writeFileSync(CJS_INDEX, lazified);
  fs.rmSync(`${CJS_INDEX}.map`, { force: true });

  console.log(`Lazified ${namespaces.length} namespace exports in ${CJS_INDEX}`);
}

lazifyCjsIndex();
